const fs = require('fs');
const path = require('path');
const TASKS_DIR = '/data/tasks';

// Load every task config once per execution
const taskConfigs = {};
if (fs.existsSync(TASKS_DIR)) {
  for (const f of fs.readdirSync(TASKS_DIR)) {
    if (!f.endsWith('.json')) continue;
    const cfg = JSON.parse(fs.readFileSync(path.join(TASKS_DIR, f), 'utf8'));
    taskConfigs[cfg.task_type] = cfg;
  }
}

const FALLBACK = { audience_fit: 0.5, cost_efficiency: 0.5 };

const binaryBuffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const doc = JSON.parse(binaryBuffer.toString('utf8'));

return doc.sources.map(s => {
  const taskType = (s.opportunity_types && s.opportunity_types[0]) || 'unknown';
  const cfg = taskConfigs[taskType];
  return {
    json: {
      ...s,
      _task_type: taskType,
      _weights: cfg ? cfg.weights : FALLBACK,
      _weights_source: cfg ? `tasks/${taskType}.json` : 'FALLBACK_default',
      __is_last: s.__is_last === true
    }
  };
});

const today = new Date().toISOString().slice(0, 10);

let raw = $json.text || $json.output || $json;
raw = raw.toString().replace(/```json/g, '').replace(/```/g, '').trim();

let arr;
try {
  arr = JSON.parse(raw);
  if (!Array.isArray(arr)) arr = [arr];
} catch (e) {
  return [{ json: {
    status: "parse_error",
    error: String(e).slice(0, 200),
    source: $('Code in JavaScript').item.json.id,
    checked_date: today
  }}];
}

function hashString(str) {
  let hash = 2166136261;
  for (let i = 0; i < str.length; i++) {
    hash ^= str.charCodeAt(i);
    hash = Math.imul(hash, 16777619);
  }
  return (hash >>> 0).toString(16);
}

const src = $('Code in JavaScript').item.json;

return arr.map(o => {
  const id = hashString(`${o.name}|${o.organizer}|${o.link}`);
  return { 
    json: { 
      ...o, 
      opportunity_id: id,
      status: "new",
      _task_type: src._task_type,
      _weights: src._weights,
      _weights_source: src._weights_source,
      checked_date: today
    } 
  };
});

const fs = require('fs');
const path = '/data/opportunities.jsonl';

const STABLE = ['name','organizer','link','city','dates','cost','deadline','source_urls'];

const stable = o => JSON.stringify(STABLE.map(k => o[k] ?? null));

const prev = fs.existsSync(path)
  ? fs.readFileSync(path, 'utf8').trim().split('\n').filter(Boolean).map(JSON.parse)
  : [];

// Keep only the latest version of each id (last write wins)
const prevById = new Map();
for (const o of prev) prevById.set(o.opportunity_id, stable(o));

return items.map(item => {

  const o = item.json;
  if (o.status === 'parse_error') {
    return { json: o };
  }

  const before = prevById.get(item.json.opportunity_id);
  const status = !before ? 'new' : (before === stable(item.json) ? 'unchanged' : 'changed');
  return { json: { ...item.json, status } };
});

const fs = require('fs');
const path = '/data/opportunities.jsonl';

const lines = items
  .filter(i => i.json && i.json.opportunity_id && i.json.status !== 'parse_error')
  .map(i => JSON.stringify(i.json))
  .join('\n');

if (lines) fs.appendFileSync(path, lines + '\n');

return items;

const fs = require('fs');
const SESSIONS = '/data/sessions';
if (!fs.existsSync(SESSIONS)) fs.mkdirSync(SESSIONS, { recursive: true });

const clamp = v => Math.min(5, Math.max(1, v));

return $input.all().map(item => {
  const o = item.json;
  const w = o._weights || {};
  const s = o.signals || {};
  const j = o.signal_justification || {};
  const missing = [];

  let sum = 0, wsum = 0;
  const contrib = [];
  for (const [k, weight] of Object.entries(w)) {
    let v = Number(s[k]);
    if (!Number.isFinite(v)) { missing.push(k); v = 3; }
    v = clamp(v);
    sum += v * weight;
    wsum += weight;
    contrib.push({ k, v, w: weight, c: v * weight });
  }

  const score = wsum > 0 ? +(sum / wsum).toFixed(2) : 0;
  contrib.sort((a, b) => b.c - a.c);
  const [top, second] = contrib;

  let why = top ? `${top.k} ${top.v}/5 — ${j[top.k] || 'no justification'}` : 'no signals';
  if (second) why += `; also ${second.k} ${second.v}/5`;
  if (missing.length) why += ` (missing: ${missing.join(',')})`;

  const row = {
    ...o,
    score,
    score_scale: '1-5',
    ranking_explanation: why,
    signals_missing: missing,
    weights_source: o._weights_source || 'unknown'
  };

  // write this row to the run's staging file
  const sessionId = String($execution.id);
  if (sessionId) {
    fs.appendFileSync(`${SESSIONS}/session_id_${sessionId}.jsonl`, JSON.stringify(row) + '\n');
  }

  return { json: row };
});

const fs = require('fs');
const SESSIONS = '/data/sessions';

const sessionId = String($execution.id);
const path = `${SESSIONS}/session_id_${sessionId}.jsonl`;

if (!fs.existsSync(path)) return [];   // empty run → report "no change"

const lines = fs.readFileSync(path, 'utf8').trim().split('\n').filter(Boolean);
return lines
  .map(l => ({ json: JSON.parse(l) }))
  .sort((a, b) => b.json.score - a.json.score);

const NOW = new Date();
const FOURTEEN_DAYS = 14 * 24 * 60 * 60 * 1000;
// 14 days in milli second

// Defensive: deadline/dates are free-text from the model
function parseDate(s) {
  if (!s || typeof s !== 'string') return null;
  const t = s.trim();
  if (/unknown|tba|tbd|^$/i.test(t)) return null;
  const d = new Date(t);
  return isNaN(d) ? null : d;
}

const all = $input.all().map(i => i.json);
const real = all.filter(o => o.status !== 'parse_error');
const markers = all.filter(o => o.status === 'parse_error');

// Sort once by score desc (Score node already sorted; keep explicit)
const sorted = [...real].sort((a, b) => (b.score || 0) - (a.score || 0));

const isNew     = o => o.status === 'new';
const isChanged = o => o.status === 'changed';

// Deadlines: only rows whose deadline parses AND falls within [now, now+14d]
const deadlines = sorted
  .map(o => {
    const d = parseDate(o.deadline);
    return d ? { ...o, _deadline_date: d.toISOString().slice(0,10) } : null;
  })
  .filter(o => o && o._deadline_date >= NOW.toISOString().slice(0,10)
            && new Date(o._deadline_date) - NOW <= FOURTEEN_DAYS);

// Unparseable deadlines: flag, don't drop (a person still needs to see them)
const unparsed = sorted.filter(o => o.deadline && o.deadline !== 'unknown'
                                 && !parseDate(o.deadline));

// Top pick: highest-scored new row; fall back to highest overall if nothing new
const topPick = sorted.find(isNew) || sorted[0] || null;

// Action needed: new + score>=4, OR any changed row, OR deadline in 3 days
const actionNeeded = sorted.filter(o => {
  if (isNew(o) && (o.score || 0) >= 4) return true;
  if (isChanged(o)) return true;
  const d = parseDate(o.deadline);
  return d && d - NOW >= 0 && d - NOW <= 3 * 24 * 60 * 60 * 1000;
});

const report = {
  generated_at: NOW.toISOString(),
  top_pick: topPick,
  action_needed: actionNeeded,
  new:      sorted.filter(isNew),
  changed:  sorted.filter(isChanged),
  unchanged_count: sorted.filter(o => o.status === 'unchanged').length,
  deadlines_14d: deadlines,
  unparsed_deadlines: unparsed.map(o => ({ name: o.name, deadline: o.deadline })),
  totals: {
    total: sorted.length,
    new: sorted.filter(isNew).length,
    changed: sorted.filter(isChanged).length,
    unchanged: sorted.filter(o => o.status === 'unchanged').length,
    parse_errors: markers.length
  }
};

const newList = report.new.slice(0, 5).map(o => `<li><strong>${o.name}</strong> — score ${o.score}</li>`).join('');
const actionList = actionNeeded.slice(0, 5).map(o => `<li><strong>${o.name}</strong> (score ${o.score}) — ${o.ranking_explanation}</li>`).join('');
const deadlineList = deadlines.map(o => `<li>${o.name} — due ${o._deadline_date}</li>`).join('');

const parseLine = report.totals.parse_errors > 0
  ? `<p><em>⚠️ ${report.totals.parse_errors} source(s) failed to parse — check session-log.jsonl (sources: ${markers.map(m => m.source || 'unknown').join(', ')}).</em></p>`
  : '';

if (report.totals.new === 0 && report.totals.changed === 0) {
  report.memo_html = `<p>No change tonight.</p>${parseLine}`;
} else {
  report.memo_html = `
    <h2>Top pick — ${topPick?.name || 'none'}</h2>
    <p>${topPick ? `Score ${topPick.score}/5. ${topPick.ranking_explanation}. Deadline: ${topPick.deadline || 'unknown'}.` : 'No opportunities tonight.'}</p>

    <h2>Action needed (${actionNeeded.length})</h2>
    <ul>${actionList || '<li>None</li>'}</ul>

    <h2>What's new (${report.totals.new} new, ${report.totals.changed} changed)</h2>
    <ul>${newList || '<li>None</li>'}</ul>

    <h2>Deadlines in 14 days (${deadlines.length})</h2>
    <ul>${deadlineList || '<li>None</li>'}</ul>

    ${parseLine}
  `;
}

return [{ json: report }];

const fs = require('fs');
const LOG = '/data/sessions/session-log.jsonl';
const SESSIONS = '/data/sessions';

// Rebuild the picture from this run's staging file + current $json report
const report = $json;
const sessionId = String($execution.id);
const staging = `${SESSIONS}/session_id_${sessionId}.jsonl`;

let rows = [];
if (fs.existsSync(staging)) {
  rows = fs.readFileSync(staging, 'utf8').trim().split('\n').filter(Boolean).map(JSON.parse);
}

const parseErrors = rows.filter(r => r.status === 'parse_error');
const sourcesChecked = new Set(rows.map(r => r.source).filter(Boolean)).size;

const entry = {
  run_at: new Date().toISOString(),
  session_id: sessionId,
  sources_checked: sourcesChecked || rows.length,
  new: report.totals?.new ?? 0,
  changed: report.totals?.changed ?? 0,
  unchanged: report.totals?.unchanged ?? 0,
  parse_errors: parseErrors.length,
  errors: parseErrors.map(r => r.source || 'unknown'),
  top_pick: report.top_pick ? { name: report.top_pick.name, score: report.top_pick.score } : null,
  total_rows: rows.length
};

fs.appendFileSync(LOG, JSON.stringify(entry) + '\n');
return [{ json: entry }];
